<?php
if(!defined('ABSPATH'))exit;
final class GRID_Cookie_Updates {
    const SLUG='grid-cookie-consent';
    const FEED='https://raw.githubusercontent.com/grid-arendal/grid-accessibility-toolbar/main/consent-updates.json';
    public static function boot(){add_filter('pre_set_site_transient_update_plugins',array(__CLASS__,'check'));add_filter('plugins_api',array(__CLASS__,'info'),10,3);add_filter('upgrader_pre_download',array(__CLASS__,'package'),10,4);}
    public static function metadata(){
        $cached=get_site_transient('grid_cookie_release');if(is_array($cached))return$cached?:null;
        $r=wp_remote_get(self::FEED,array('timeout'=>8,'redirection'=>0,'headers'=>array('Accept'=>'application/json')));if(is_wp_error($r)||wp_remote_retrieve_response_code($r)!==200){set_site_transient('grid_cookie_release',array(),300);return null;}
        $d=json_decode(wp_remote_retrieve_body($r),true);if(!self::valid($d)){set_site_transient('grid_cookie_release',array(),300);return null;}set_site_transient('grid_cookie_release',$d,12*HOUR_IN_SECONDS);return$d;
    }
    public static function valid($d){return is_array($d)&&($d['slug']??'')===self::SLUG&&is_string($d['version']??null)&&preg_match('/^\d+\.\d+\.\d+$/D',$d['version'])&&($d['download_url']??'')==='https://github.com/grid-arendal/grid-accessibility-toolbar/releases/download/consent-v'.$d['version'].'/'.self::SLUG.'-'.$d['version'].'.zip'&&is_string($d['sha256']??null)&&preg_match('/^[a-f0-9]{64}$/D',$d['sha256']);}
    public static function check($value){if(!is_object($value)||empty($value->checked))return$value;$d=self::metadata();if(!$d)return$value;$file=plugin_basename(GRID_Cookie_Consent::FILE);$item=(object)array('id'=>self::SLUG,'slug'=>self::SLUG,'plugin'=>$file,'new_version'=>$d['version'],'url'=>'https://github.com/grid-arendal/grid-accessibility-toolbar/tree/main/consent','package'=>$d['download_url'],'requires'=>$d['requires']??'6.4','requires_php'=>$d['requires_php']??'7.4');if(version_compare($d['version'],$value->checked[$file]??GRID_Cookie_Consent::VERSION,'>'))$value->response[$file]=$item;else$value->no_update[$file]=$item;return$value;}
    public static function info($result,$action,$args){if($action!=='plugin_information'||($args->slug??'')!==self::SLUG)return$result;$d=self::metadata();if(!$d)return$result;return(object)array('name'=>'GRID Cookie Consent','slug'=>self::SLUG,'version'=>$d['version'],'author'=>'GRID-Arendal','homepage'=>'https://github.com/grid-arendal/grid-accessibility-toolbar/tree/main/consent','download_link'=>$d['download_url'],'requires'=>$d['requires']??'6.4','requires_php'=>$d['requires_php']??'7.4','sections'=>array('description'=>'Locally hosted, strict opt-in consent controls. Supports compliance; site-specific configuration and review remain required.','changelog'=>esc_html($d['notes']??'Published stable release.')));}
    public static function package($reply,$url,$upgrader,$extra){if(($extra['plugin']??'')!==plugin_basename(GRID_Cookie_Consent::FILE))return$reply;if(is_wp_error($reply))return$reply;$d=self::metadata();if(!$d||$url!==$d['download_url'])return new WP_Error('grid_cookie_update','No verified published consent package is available.');if($reply!==false){if(is_string($reply)&&is_file($reply)&&hash_equals($d['sha256'],hash_file('sha256',$reply)))return$reply;return new WP_Error('grid_cookie_override','An earlier package override could not be verified.');}require_once ABSPATH.'wp-admin/includes/file.php';$tmp=download_url($url,30);if(is_wp_error($tmp))return$tmp;if(!hash_equals($d['sha256'],hash_file('sha256',$tmp))){wp_delete_file($tmp);return new WP_Error('grid_cookie_hash','Update checksum mismatch; package rejected.');}return$tmp;}
}
